#define CHECK(x) do{++checks;if(!(x)){fprintf(stderr,"MP stats check %u line %d: %s\n",checks,__LINE__,#x);exit(1);}}while(0)
typedef struct {MCObject object;int32_t points;bool force,readOnly;unsigned notifications;} WitnessScore;
typedef struct {MCObject object;MCObject *values[2];size_t length;} Objectives;
typedef struct {MCObject object;Objectives *list;size_t next;} Iterator;
typedef struct {
    MCObject object;StatisticsFile *file;MCGameplayPlayer *player;StatBase *stat;NBTString *name;
    WitnessScore *scores[2];Objectives *objectives;StatisticsFileIntMap *sent;unsigned sends,chats,taken;
    char events[256];size_t used;unsigned calls,failAt;int32_t tick;bool announce;
    char scoreEvents[32];size_t scoreUsed;
} Context;
static void objectives_trace(MCObject *o,MCObjectVisitor v,void *c){Objectives *l=(Objectives *)o;for(size_t i=0;i<2;i++)l->values[i]=v(l->values[i],c);}
static void iterator_trace(MCObject *o,MCObjectVisitor v,void *c){Iterator *i=(Iterator *)o;i->list=(Objectives *)v((MCObject *)i->list,c);}
static void context_trace(MCObject *o,MCObjectVisitor v,void *c){Context *x=(Context *)o;x->file=(StatisticsFile *)v((MCObject *)x->file,c);x->player=(MCGameplayPlayer *)v((MCObject *)x->player,c);x->stat=(StatBase *)v((MCObject *)x->stat,c);x->name=(NBTString *)v((MCObject *)x->name,c);x->objectives=(Objectives *)v((MCObject *)x->objectives,c);x->sent=(StatisticsFileIntMap *)v((MCObject *)x->sent,c);for(size_t i=0;i<2;i++)x->scores[i]=(WitnessScore *)v((MCObject *)x->scores[i],c);}
static const MCObjectClass score_class={"fixture.WitnessScore",MCObjectHeap_plainClone,NULL,NULL},objectives_class={"fixture.objectives",MCObjectHeap_plainClone,objectives_trace,NULL},iterator_class={"fixture.iterator",MCObjectHeap_plainClone,iterator_trace,NULL},context_class={"fixture.stats dependencies",MCObjectHeap_plainClone,context_trace,NULL};
static bool event(Context *c,char ch){CHECK(MCObjectHeap_hasBorrowers(c->object.heap)&&!MCObjectHeap_collect(c->object.heap));CHECK(c->used+1<sizeof(c->events));c->events[c->used++]=ch;c->events[c->used]=0;c->calls++;MCObjectHeap_touch(c->object.heap);if(c->failAt==c->calls){MCObjectHeap_fail(c->object.heap);return false;}return true;}
static void score_event(Context *c,char ch){CHECK(c->scoreUsed+1<sizeof(c->scoreEvents));c->scoreEvents[c->scoreUsed++]=ch;c->scoreEvents[c->scoreUsed]=0;MCObjectHeap_touch(c->object.heap);}
static bool announcing(MCObject *o,MCObject *server){Context *c=(Context *)o;CHECK(server==o);return event(c,'A')&&c->announce;}
static bool chat(MCObject *o,MCObject *server,MCObject *player,StatBase *stat,bool taken){Context *c=(Context *)o;CHECK(server==o&&player==(MCObject *)c->player&&stat==c->stat);if(!event(c,taken?'R':'U'))return false;c->chats++;c->taken+=taken;return true;}
static int32_t tick(MCObject *o,MCObject *server){CHECK(server==o);Context *c=(Context *)o;event(c,'T');return c->tick;}
static bool send_stats(MCObject *o,MCObject *player,StatisticsFileIntMap *map){Context *c=(Context *)o;CHECK(player==(MCObject *)c->player&&map);if(!event(c,'S'))return false;c->sent=map;c->sends++;return true;}
static const StatisticsFileDependencies file_dependencies={announcing,chat,tick,send_stats};
static MCObject *board(MCObject *o,MCGameplayPlayer *p){Context *c=(Context *)o;CHECK(p==c->player);return event(c,'B')?o:NULL;}
static MCObject *criteria(MCObject *o,StatBase *s){Context *c=(Context *)o;CHECK(s==c->stat);return event(c,'C')?(MCObject *)s:NULL;}
static MCObject *objectives(MCObject *o,MCObject *board,MCObject *criterion){Context *c=(Context *)o;CHECK(board==o&&criterion==(MCObject *)c->stat);if(!event(c,'O'))return NULL;score_event(c,'O');return (MCObject *)c->objectives;}
static MCObject *iterator(MCObject *o,MCObject *list){Context *c=(Context *)o;CHECK(list==(MCObject *)c->objectives);if(!event(c,'I'))return NULL;Iterator *i=(Iterator *)MCObjectHeap_alloc(o->heap,sizeof(*i),&iterator_class);if(i)i->list=(Objectives *)list;return (MCObject *)i;}
static bool has_next(MCObject *o,MCObject *it){Context *c=(Context *)o;Iterator *i=(Iterator *)it;return event(c,'?')&&i->next<i->list->length;}
static MCObject *next(MCObject *o,MCObject *it){Context *c=(Context *)o;Iterator *i=(Iterator *)it;CHECK(i->next<i->list->length);return event(c,'N')?i->list->values[i->next++]:NULL;}
static NBTString *name(MCObject *o,MCGameplayPlayer *p){Context *c=(Context *)o;CHECK(p==c->player);return event(c,'P')?c->name:NULL;}
static MCObject *get_score(MCObject *o,MCObject *board,const NBTString *name,MCObject *objective){Context *c=(Context *)o;CHECK(board==o&&name==c->name);if(!event(c,'V'))return NULL;score_event(c,'V');CHECK(objective==(MCObject *)c->scores[0]||objective==(MCObject *)c->scores[1]);return objective;}
static bool set_score(MCObject *o,MCObject *object,int32_t points){Context *c=(Context *)o;WitnessScore *s=(WitnessScore *)object;if(!event(c,'='))return false;int32_t old=s->points;s->points=points;if(old!=points||s->force){s->force=false;s->notifications++;score_event(c,'D');}MCObjectHeap_touch(o->heap);return true;}
static bool increase(MCObject *o,MCObject *object,int32_t amount){Context *c=(Context *)o;WitnessScore *s=(WitnessScore *)object;if(!event(c,'+'))return false;if(s->readOnly){MCObjectHeap_fail(o->heap);return false;}uint32_t b=(uint32_t)s->points+(uint32_t)amount;int32_t value;memcpy(&value,&b,sizeof(value));return set_score(o,object,value);}
static const EntityPlayerMPStatsDependencies mp_dependencies={board,criteria,objectives,iterator,has_next,next,name,get_score,increase,set_score};
static NBTString *display(MCObject *o,const ItemStack *s){(void)s;return ((Context *)o)->name;}
static bool uncalled_craft(ItemStack *s,MCObject *w,MCObject *p,int32_t n){(void)s;(void)w;(void)n;MCObjectHeap_fail(p->heap);return false;}
static bool uncalled_achievement(MCObject *p,mc_crafting_achievement a){(void)a;MCObjectHeap_fail(p->heap);return false;}
static bool uncalled_drop(MCObject *p,ItemStack *s,bool b){(void)s;(void)b;MCObjectHeap_fail(p->heap);return false;}
static const MCGameplayCraftingEffects effects={uncalled_craft,uncalled_achievement,uncalled_drop};
typedef struct {MCGameplay game;Context *context;mc_crafting_dispatch dispatch;MCObjectRootScope scope;} Fixture;
