static void achievement_gate_and_dirty(void){Fixture f;init(&f);Context *c=f.context;MCObjectHeap *h=f.game.heap;Achievement *parent=Achievement_newIdentity(h,NBTString_fromASCII(h,"native.parent"),NULL),*child=Achievement_newIdentity(h,NBTString_fromASCII(h,"native.child"),parent);CHECK(parent&&child);c->stat=&child->base;CHECK(EntityPlayerMP_addStat(c->player,c->stat,3,(MCObject *)c,&mp_dependencies));CHECK(StatFileWriter_statCount(&c->file->base)==0&&c->scores[0]->points==3&&!c->sends&&!StatisticsFileStatSet_size(c->file->field_150888_e));CHECK(StatFileWriter_unlockAchievementBase(&c->file->base,NULL,&parent->base,1));reset_log(c);c->announce=true;CHECK(EntityPlayerMP_addStat(c->player,c->stat,1,(MCObject *)c,&mp_dependencies));CHECK(StatFileWriter_readStat(&c->file->base,c->stat)==1&&c->chats==1&&c->sends==1&&c->scores[0]->points==4);CHECK(strcmp(c->events,"AUBCOI?NBPV+=?NBPV+=?TS")==0);CHECK(!StatisticsFile_func_150879_e(c->file)&&StatisticsFileStatSet_size(c->file->field_150888_e)==0&&StatisticsFileIntMap_size(c->sent)==1);StatBase *key;int32_t value;CHECK(StatisticsFileIntMap_entry(c->sent,0,&key,&value)&&key==c->stat&&value==1);reset_log(c);CHECK(EntityPlayerMP_func_175145_a(c->player,c->stat,(MCObject *)c,&mp_dependencies));CHECK(c->chats==2&&c->taken==1&&c->sends==2&&strcmp(c->events,"ARBCOI?NBPV=?NBPV=?TS")==0);CHECK(StatFileWriter_readStat(&c->file->base,c->stat)==0&&c->scores[0]->points==0);CHECK(!MCObjectHeap_failed(h));finish(&f);}
