static void arithmetic(bool print){const int32_t amounts[]={INT32_MIN,-3,-1,0,1,4,INT32_MAX},initials[]={INT32_MIN,-1,0,1,INT32_MAX};for(size_t i=0;i<sizeof(initials)/sizeof(*initials);i++)for(size_t j=0;j<sizeof(amounts)/sizeof(*amounts);j++){Fixture f;init(&f);Context *c=f.context;for(size_t k=0;k<2;k++){c->scores[k]->points=initials[i];c->scores[k]->force=false;}CHECK(EntityPlayerMP_addStat(c->player,c->stat,amounts[j],(MCObject *)c,&mp_dependencies));uint32_t b=(uint32_t)initials[i]+(uint32_t)amounts[j];int32_t value;memcpy(&value,&b,sizeof(value));CHECK(c->scores[0]->points==value&&c->scores[1]->points==value&&StatFileWriter_readStat(&c->file->base,c->stat)==amounts[j]);unsigned boards=0,names=0;for(size_t n=0;n<c->used;n++){boards+=c->events[n]=='B';names+=c->events[n]=='P';}CHECK(boards==3&&names==2);if(print)printf("%d %d %d %d %d %u %u %u %s\n",initials[i],amounts[j],StatFileWriter_readStat(&c->file->base,c->stat),c->scores[0]->points,c->scores[1]->points,c->scores[0]->notifications+c->scores[1]->notifications,names,boards,c->scoreEvents);reset_log(c);CHECK(EntityPlayerMP_func_175145_a(c->player,c->stat,(MCObject *)c,&mp_dependencies));CHECK(StatFileWriter_readStat(&c->file->base,c->stat)==0&&c->scores[0]->points==0&&c->scores[1]->points==0&&!MCObjectHeap_failed(f.game.heap));finish(&f);}}
